func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "Usage: mlpipe <command> [args...]")
		fmt.Fprintln(os.Stderr, "Commands: validate, plan, run, report, artifacts")
		os.Exit(1)
	}

	cmd := os.Args[1]
	args := os.Args[2:]

	switch cmd {
	case "validate":
		os.Exit(cmdValidate(args))
	case "plan":
		os.Exit(cmdPlan(args))
	case "run":
		os.Exit(cmdRun(args))
	case "report":
		os.Exit(cmdReport(args))
	case "artifacts":
		os.Exit(cmdArtifacts(args))
	default:
		fmt.Fprintf(os.Stderr, "error: command %q is not implemented\n", cmd)
		os.Exit(1)
	}
