func cmdValidate(args []string) int {
	if len(args) < 1 {
		fmt.Fprintln(os.Stderr, "Usage: mlpipe validate <pipeline.yaml>")
		return 1
	}
	p, err := loadPipeline(args[0])
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	errs := validatePipeline(p)
	if len(errs) > 0 {
		for _, e := range errs {
			fmt.Println(e)
		}
		return 1
	}
	return 0
}

func cmdPlan(args []string) int {
	if len(args) < 1 {
		fmt.Fprintln(os.Stderr, "Usage: mlpipe plan <pipeline.yaml>")
		return 1
	}
	p, err := loadPipeline(args[0])
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	if errs := validatePipeline(p); len(errs) > 0 {
		for _, e := range errs {
			fmt.Fprintln(os.Stderr, e)
		}
		return 1
	}
	groups, err := topologicalGroups(p)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	combos := parameterCombinations(p)
	out := struct {
		StagesOrder            [][]string                 `json:"stages_order"`
		TotalExperiments       int                        `json:"total_experiments"`
		ParameterCombinations  []map[string]interface{}   `json:"parameter_combinations"`
	}{
		StagesOrder:           groups,
		TotalExperiments:      len(combos),
		ParameterCombinations: combos,
	}
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(out); err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	return 0
}

func cmdRun(args []string) int {
	pipelineFile, experimentIndex, resume, err := parseRunArgs(args)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	p, err := loadPipeline(pipelineFile)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	if errs := validatePipeline(p); len(errs) > 0 {
		for _, e := range errs {
			fmt.Fprintln(os.Stderr, e)
		}
		return 1
	}
	combos := parameterCombinations(p)
	if experimentIndex >= 0 {
		if experimentIndex >= len(combos) {
			fmt.Fprintf(os.Stderr, "error: experiment index %d out of range (0..%d)\n", experimentIndex, len(combos)-1)
			return 1
		}
		combos = []map[string]interface{}{combos[experimentIndex]}
	}
	for _, combo := range combos {
		id := experimentID(combo)
		fmt.Fprintf(os.Stderr, "Running experiment %s\n", id)
		if err := runExperiment(p, combo, resume); err != nil {
			fmt.Fprintln(os.Stderr, "error:", err)
			return 1
		}
	}
	return 0
}

func cmdReport(args []string) int {
	if len(args) < 1 {
		fmt.Fprintln(os.Stderr, "Usage: mlpipe report <pipeline.yaml>")
		return 1
	}
	p, err := loadPipeline(args[0])
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	if errs := validatePipeline(p); len(errs) > 0 {
		for _, e := range errs {
			fmt.Fprintln(os.Stderr, e)
		}
		return 1
	}
	return reportPipeline(p)
}

func cmdArtifacts(args []string) int {
	pipelineFile, list, gc, err := parseArtifactsArgs(args)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	p, err := loadPipeline(pipelineFile)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	if gc {
		return artifactsGC(p)
	}
	_ = list
	return artifactsList()
}

func parseRunArgs(args []string) (string, int, bool, error) {
	pipelineFile := ""
	experimentIndex := -1
	resume := false
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--experiment":
			if i+1 >= len(args) {
				return "", 0, false, fmt.Errorf("--experiment requires an index")
			}
			idx, err := strconv.Atoi(args[i+1])
			if err != nil {
				return "", 0, false, fmt.Errorf("invalid experiment index: %v", err)
			}
			experimentIndex = idx
			i++
		case "--resume":
			resume = true
		default:
			if pipelineFile == "" {
				pipelineFile = args[i]
			} else {
				return "", 0, false, fmt.Errorf("unexpected argument: %s", args[i])
			}
		}
	}
	if pipelineFile == "" {
		return "", 0, false, fmt.Errorf("usage: mlpipe run <pipeline.yaml> [--experiment <index>] [--resume]")
	}
	return pipelineFile, experimentIndex, resume, nil
}

func parseArtifactsArgs(args []string) (string, bool, bool, error) {
	pipelineFile := ""
	list := false
	gc := false
	for _, arg := range args {
		switch arg {
		case "--list":
			list = true
		case "--gc":
			gc = true
		default:
			if pipelineFile == "" {
				pipelineFile = arg
			} else {
				return "", false, false, fmt.Errorf("unexpected argument: %s", arg)
			}
		}
	}
	if pipelineFile == "" {
		return "", false, false, fmt.Errorf("usage: mlpipe artifacts <pipeline.yaml> [--list] [--gc]")
	}
	return pipelineFile, list, gc, nil
}
