    Size         int64  `json:"size"`
}

type ArtifactIndex struct {
    Entries []ArtifactEntry `json:"entries"`
}

type yamlLine struct {
    indent  int
    content string
}

func loadPipeline(path string) (*Pipeline, error) {
    data, err := os.ReadFile(path)
    if err != nil {
        return nil, err
    }
    v, err := parseYAML(data)
    if err != nil {
        return nil, err
    }
    return mapToPipeline(v)
}

func parseYAML(data []byte) (interface{}, error) {
    var lines []yamlLine
    for _, raw := range strings.Split(string(data), "\n") {
        raw = strings.TrimRight(raw, "\r")
        trimmed := strings.TrimSpace(raw)
        if trimmed == "" || strings.HasPrefix(trimmed, "#") {
            continue
        }
        indent := 0
        for indent < len(raw) && raw[indent] == ' ' {
            indent++
        }
        content := strings.TrimRight(raw[indent:], " ")
        lines = append(lines, yamlLine{indent: indent, content: content})
    }
    if len(lines) == 0 {
        return nil, nil
    }
    v, idx := parseBlock(lines, 0, 0)
    if idx < len(lines) {
        return nil, fmt.Errorf("unexpected YAML structure at line: %q", lines[idx].content)
    }
    return v, nil
}

func parseBlock(lines []yamlLine, idx int, indent int) (interface{}, int) {
    if idx >= len(lines) || lines[idx].indent < indent {
        return nil, idx
    }
    if strings.HasPrefix(lines[idx].content, "- ") || lines[idx].content == "-" {
        return parseSequence(lines, idx, indent)
    }
    return parseMapping(lines, idx, indent)
}

func parseSequence(lines []yamlLine, idx int, indent int) (interface{}, int) {
    seq := []interface{}{}
    for idx < len(lines) && lines[idx].indent == indent && (strings.HasPrefix(lines[idx].content, "- ") || lines[idx].content == "-") {
        content := strings.TrimPrefix(lines[idx].content, "-")
        content = strings.TrimLeft(content, " ")
        if content == "" {
            val, next := parseBlock(lines, idx+1, indent+2)
            seq = append(seq, val)
            idx = next
            continue
        }
        if isMappingStart(content) {
            sublines := []yamlLine{{indent: indent + 2, content: content}}
            start := idx + 1
            for start < len(lines) && lines[start].indent > indent {
                sublines = append(sublines, lines[start])
                start++
            }
            val, _ := parseBlock(sublines, 0, indent+2)
            seq = append(seq, val)
            idx = start
        } else {
            seq = append(seq, parseScalar(content))
            idx++
        }
    }
    return seq, idx
}

func parseMapping(lines []yamlLine, idx int, indent int) (interface{}, int) {
    m := map[string]interface{}{}
    for idx < len(lines) && lines[idx].indent == indent {
        content := lines[idx].content
        if strings.HasPrefix(content, "- ") || content == "-" {
            break
        }
        key, value, ok := splitKeyValue(content)
        if !ok {
            return nil, idx
        }
        if value != "" {
            m[key] = parseScalar(value)
            idx++
        } else {
            val, next := parseBlock(lines, idx+1, indent+2)
            m[key] = val
            idx = next
        }
    }
    return m, idx
}

func isMappingStart(s string) bool {
    if strings.HasPrefix(s, "[") || strings.HasPrefix(s, "{") {
        return false
    }
    _, _, ok := splitKeyValue(s)
    return ok
}

func splitKeyValue(s string) (string, string, bool) {
    inQuote := false
    quoteChar := byte(0)
    for i := 0; i < len(s); i++ {
        c := s[i]
        if inQuote {
            if c == quoteChar {
                inQuote = false
            }
            continue
        }
        if c == '"' || c == '\'' {
            inQuote = true
            quoteChar = c
            continue
        }
        if c == ':' {
            if i+1 >= len(s) || s[i+1] == ' ' {
                key := strings.TrimSpace(s[:i])
                value := strings.TrimSpace(s[i+1:])
                key = unquoteScalar(key)
                return key, value, true
            }
        }
    }
    return "", "", false
}

func parseScalar(s string) interface{} {
    s = strings.TrimSpace(s)
    if s == "" {
        return ""
    }
    if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
        return parseInlineList(s)
    }
    if strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}") {
        return parseInlineMap(s)
    }
    if len(s) >= 2 && (s[0] == '"' && s[len(s)-1] == '"' || s[0] == '\'' && s[len(s)-1] == '\'') {
        return unquoteScalar(s)
    }
    if s == "true" {
        return true
    }
    if s == "false" {
        return false
    }
    if n, err := strconv.Atoi(s); err == nil {
        return n
    }
    if f, err := strconv.ParseFloat(s, 64); err == nil {
        return f
    }
    return s
}

func parseInlineList(s string) interface{} {
    inner := strings.TrimSpace(s[1 : len(s)-1])
    if inner == "" {
        return []interface{}{}
    }
    parts := splitCommas(inner)
    out := make([]interface{}, 0, len(parts))
    for _, p := range parts {
        out = append(out, parseScalar(strings.TrimSpace(p)))
    }
    return out
}

func parseInlineMap(s string) interface{} {
    inner := strings.TrimSpace(s[1 : len(s)-1])
    if inner == "" {
        return map[string]interface{}{}
    }
    parts := splitCommas(inner)
    m := map[string]interface{}{}
    for _, p := range parts {
        key, value, ok := splitKeyValue(strings.TrimSpace(p))
        if ok {
            m[key] = parseScalar(value)
        }
    }
    return m
}

func splitCommas(s string) []string {
    var parts []string
    inQuote := false
    quoteChar := byte(0)
    depth := 0
    start := 0
    for i := 0; i < len(s); i++ {
        c := s[i]
        if inQuote {
            if c == quoteChar {
                inQuote = false
            }
            continue
        }
        if c == '"' || c == '\'' {
            inQuote = true
            quoteChar = c
            continue
        }
        if c == '[' || c == '{' {
            depth++
            continue
        }
        if c == ']' || c == '}' {
            depth--
            continue
        }
        if c == ',' && depth == 0 {
            parts = append(parts, s[start:i])
            start = i + 1
        }
    }
    parts = append(parts, s[start:])
    return parts
}

func unquoteScalar(s string) string {
    s = strings.TrimSpace(s)
    if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
        unq, err := strconv.Unquote(s)
        if err == nil {
            return unq
        }
        return s[1 : len(s)-1]
    }
    if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
        return strings.ReplaceAll(s[1:len(s)-1], "''", "'")
    }
    return s
}

func mapToPipeline(v interface{}) (*Pipeline, error) {
    p := &Pipeline{}
    root := asMap(v)
    if root == nil {
        return p, nil
    }
    p.Name = asString(root["name"])
    p.Version = asString(root["version"])
    if params, ok := root["parameters"].(map[string]interface{}); ok {
        keys := make([]string, 0, len(params))
        for k := range params {
            keys = append(keys, k)
        }
        sort.Strings(keys)
        for _, k := range keys {
            pm := asMap(params[k])
            p.Parameters = append(p.Parameters, Parameter{Name: k, Values: asSlice(pm["values"])})
        }
    }
    for _, sv := range asSlice(root["stages"]) {
        sm := asMap(sv)
        stage := Stage{
            Name:    asString(sm["name"]),
            Command: asString(sm["command"]),
        }
        stage.DependsOn = toStringSlice(asSlice(sm["depends_on"]))
        stage.Env = toStringMap(asMap(sm["env"]))
        for _, mv := range asSlice(sm["metrics"]) {
            mm := asMap(mv)
            stage.Metrics = append(stage.Metrics, Metric{Name: asString(mm["name"]), Objective: asString(mm["objective"])})
        }
        if rv := asMap(sm["retry"]); rv != nil {
            stage.Retry = &Retry{MaxAttempts: asInt(rv["max_attempts"]), BackoffSeconds: asFloat(rv["backoff_seconds"])}
        }
        if cv := asMap(sm["condition"]); cv != nil {
            stage.Condition = &Condition{Metric: asString(cv["metric"]), Operator: asString(cv["operator"]), Threshold: asFloat(cv["threshold"])}
        }
        for _, ov := range asSlice(sm["outputs"]) {
            om := asMap(ov)
            stage.Outputs = append(stage.Outputs, ArtifactRef{Path: asString(om["path"]), Type: asString(om["type"])})
        }
        for _, iv := range asSlice(sm["inputs"]) {
            im := asMap(iv)
            stage.Inputs = append(stage.Inputs, ArtifactRef{Path: asString(im["path"]), Type: asString(im["type"])})
        }
        p.Stages = append(p.Stages, stage)
    }
    return p, nil
}

func asMap(v interface{}) map[string]interface{} {
    if m, ok := v.(map[string]interface{}); ok {
        return m
    }
    return nil
}

func asSlice(v interface{}) []interface{} {
    if s, ok := v.([]interface{}); ok {
        return s
    }
    return nil
}

func asString(v interface{}) string {
    if v == nil {
        return ""
    }
    switch x := v.(type) {
    case string:
        return x
    case int:
        return strconv.Itoa(x)
    case float64:
        return formatFloat(x)
    case bool:
        return strconv.FormatBool(x)
    default:
        return fmt.Sprint(x)
    }
}

func asInt(v interface{}) int {
    switch x := v.(type) {
    case int:
        return x
    case float64:
        return int(x)
    case string:
        n, _ := strconv.Atoi(x)
        return n
    default:
        return 0
    }
}

func asFloat(v interface{}) float64 {
    switch x := v.(type) {
    case float64:
        return x
    case int:
        return float64(x)
    case string:
        f, _ := strconv.ParseFloat(x, 64)
        return f
    default:
        return 0
    }
}

func toStringSlice(v []interface{}) []string {
    out := make([]string, 0, len(v))
    for _, item := range v {
        out = append(out, asString(item))
    }
    return out
}

func toStringMap(m map[string]interface{}) map[string]string {
    out := make(map[string]string)
    for k, v := range m {
        out[k] = asString(v)
    }
    return out
}

func formatFloat(f float64) string {
    return strconv.FormatFloat(f, 'g', -1, 64)
}
