func parseYAML(data []byte) (interface{}, error) {
    var lines []yamlLine
    for _, raw := range strings.Split(string(data), "\n") {
        raw = strings.TrimRight(raw, "\r")
        trimmed := strings.TrimSpace(raw)
        if trimmed == "" || strings.HasPrefix(trimmed, "#") {
            continue
        }
        indent := 0
        for indent < len(raw) && raw[indent] == ' ' {
            indent++
        }
        content := strings.TrimRight(raw[indent:], " ")
        lines = append(lines, yamlLine{indent: indent, content: content})
    }
    if len(lines) == 0 {
        return nil, nil
    }
    v, idx := parseBlock(lines, 0, 0)
    if idx < len(lines) {
        return nil, fmt.Errorf("unexpected YAML structure at line: %q", lines[idx].content)
    }
    return v, nil
}

func parseBlock(lines []yamlLine, idx int, indent int) (interface{}, int) {
    if idx >= len(lines) || lines[idx].indent < indent {
        return nil, idx
